// Holt die Vivino-Rangliste (inoffizielle Explore-Schnittstelle) und wandelt sie ins Katalogformat der App.
// Benoetigt in n8n: NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');
const MAX_PAGES = 40;       // Obergrenze je Lauf, bewusst klein
const PAUSE_MS = 4000;      // Hoeflichkeitspause zwischen den Seiten
const TYPES = { 1: 'red', 2: 'white', 3: 'sparkling', 4: 'rose' };   // 7 (Dessert) bleibt leer

const norm = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]/g, '');
const key = (producer, name, vintage) =>
  'wine_' + crypto.createHash('md5').update([norm(producer), norm(name), String(Math.max(0, vintage))].join('_')).digest('hex');

const out = new Map();
for (let page = 1; page <= MAX_PAGES; page++) {
  const res = await this.helpers.httpRequest({
    url: 'https://www.vivino.com/api/explore/explore',
    qs: { 'country_codes[]': 'ch', 'wine_type_ids[]': [1, 2, 3, 4, 7], currency_code: 'CHF',
          order_by: 'ratings_average', order: 'desc', page },
    headers: { 'User-Agent': 'Mozilla/5.0 (compatible; WyychaellerliCatalog/1.0)', Accept: 'application/json' },
    json: true,
  });
  const matches = res?.explore_vintage?.matches || [];
  if (!matches.length) break;
  for (const m of matches) {
    const v = m.vintage, w = v.wine;
    const vintage = Number.isInteger(v.year) ? v.year : 0;           // "N.V." wird 0 = ohne Jahrgang
    const producer = w.winery?.name || '';
    const name = w.name || '';
    const k = key(producer, name, vintage);
    if (out.has(k)) continue;
    out.set(k, {
      key: k, name, producer, vintage,
      region: w.region?.name_en || w.region?.name || '',
      country: w.region?.country?.native_name || '',
      typeRaw: TYPES[w.type_id] || '',
      source: 'vivino', sourceID: String(w.id),
      rating: v.statistics?.ratings_average ?? null,
      ratingsCount: v.statistics?.ratings_count ?? 0,
    });
  }
  await new Promise(r => setTimeout(r, PAUSE_MS));
}
const wines = [...out.values()];
return [{ json: { generatedAt: new Date().toISOString(), count: wines.length, wines } }];

// Schreibt die aufbereitete Liste direkt in den oeffentlichen CloudKit-Katalog (CatalogWine).
// Umgebungsvariablen in n8n: CK_KEY_ID, CK_PRIVATE_KEY (PEM, Zeilenumbrueche als \n), CK_ENV (development oder production)
// Zusaetzlich: NODE_FUNCTION_ALLOW_BUILTIN=crypto und NODE_FUNCTION_ALLOW_EXTERNAL leer lassen.
const crypto = require('crypto');
const KEY_ID = $env.CK_KEY_ID, ENV = $env.CK_ENV || 'development';
const PEM = ($env.CK_PRIVATE_KEY || '').replace(/\\n/g, '\n');
const LIMIT = Number($env.CK_LIMIT || 0);          // zum Testen z. B. 5; 0 = alle
const CONTAINER = 'iCloud.com.sondinetwork.weinkeller.app';
const SUBPATH = `/database/1/${CONTAINER}/${ENV}/public/records/modify`;
const FILLERS = new Set(['domaine','chateau','weingut','cantina','cantine','bodega','bodegas','tenuta','azienda','agricola','cave','caves','maison','winery','estate','vin','vino','wein','wine','rouge','rosso','rotwein','blanc','bianco','weisswein','the','les','del','della','von','und']);

const tokens = (name, producer) => {
  const words = (producer + ' ' + name).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .split(/[^a-z0-9]+/).filter(w => w.length >= 3 && !FILLERS.has(w) && !/^\d+$/.test(w));
  return [...new Set(words)];
};

let wines = $input.first().json.wines;
if (LIMIT > 0) wines = wines.slice(0, LIMIT);

const op = w => ({
  operationType: 'create',            // create schlaegt bei vorhandenem Schluessel fehl: nichts wird ueberschrieben
  record: {
    recordType: 'CatalogWine',
    recordName: w.key,
    fields: {
      name: { value: w.name },
      producer: { value: w.producer },
      vintage: { value: w.vintage, type: 'INT64' },
      grape: { value: '' },
      region: { value: w.region },
      country: { value: w.country },
      typeRaw: { value: w.typeRaw },
      alcoholPercent: { value: 0, type: 'DOUBLE' },
      searchTokens: { value: tokens(w.name, w.producer) },
      source: { value: 'vivino' },
      sourceID: { value: w.sourceID },
      adminEdited: { value: 0, type: 'INT64' },
    },
  },
});

let created = 0, existed = 0; const errors = [];
for (let i = 0; i < wines.length; i += 100) {
  const body = JSON.stringify({ operations: wines.slice(i, i + 100).map(op) });
  const date = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
  const bodyHash = crypto.createHash('sha256').update(body).digest('base64');
  const signature = crypto.createSign('sha256').update(`${date}:${bodyHash}:${SUBPATH}`).sign(PEM, 'base64');
  const res = await this.helpers.httpRequest({
    method: 'POST', url: 'https://api.apple-cloudkit.com' + SUBPATH, body, json: false,
    headers: { 'Content-Type': 'text/plain',
      'X-Apple-CloudKit-Request-KeyID': KEY_ID,
      'X-Apple-CloudKit-Request-ISO8601Date': date,
      'X-Apple-CloudKit-Request-SignatureV1': signature },
  });
  const parsed = typeof res === 'string' ? JSON.parse(res) : res;
  if (parsed.serverErrorCode) throw new Error(`CloudKit: ${parsed.serverErrorCode} ${parsed.reason || ''}`);
  for (const r of parsed.records || []) {
    if (!r.serverErrorCode) created++;
    else if (r.serverErrorCode === 'CONFLICT' || /exist/i.test(r.reason || '')) existed++;
    else errors.push(`${r.recordName}: ${r.serverErrorCode} ${r.reason || ''}`);
  }
}
return [{ json: { env: ENV, versucht: wines.length, neu: created, schonVorhanden: existed, fehler: errors.slice(0, 10), fehlerAnzahl: errors.length } }];
